const items = $input.all();

return items.map(({ json }) => {
  const title = String(json.title ?? '').trim();
  const url = String(json.link ?? json.guid ?? '').trim().split('#')[0];
  const publishedAt = json.isoDate ?? json.pubDate ?? null;
  const description = String(json.contentSnippet ?? json.content ?? '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  return {
    json: {
      article_id: url || title.toLowerCase().replace(/\W+/g, '-'),
      title,
      url,
      published_at: publishedAt,
      source: 'BBC News Business',
      source_tier: 'TIER_2_STABLE_MEDIA',
      rss_description: description,
      feed: 'BBC Business',
      fetched_at: new Date().toISOString(),
      dedup_key: url || title,
    },
  };
});

const seen = new Set();

return $input.all().filter(({ json }) => {
  const key = String(json.dedup_key || json.url || json.title || '').trim();
  if (!key || seen.has(key)) return false;
  seen.add(key);
  return true;
});

const base = $('Code in JavaScript1').first().json;
const rawArticle = String($json.data ?? '');

return [{
  json: {
    ...base,
    raw_article: rawArticle,
    fetched_url: base.url,
    fetch_method: 'jina_reader',
    article_text_length: rawArticle.length,
  },
}];

