const base = $('Code in JavaScript2').first().json;
const response = $json?.data ?? $json;
const raw = response?.choices?.[0]?.message?.content
  ?? response?.choices?.[0]?.text
  ?? response?.content
  ?? '';

const cleaned = String(raw)
  .replace(/^\s*\`\`\`json\s*/i, '')
  .replace(/\s*\`\`\`\s*$/i, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  throw new Error('Researcher JSON parse failed: ' + error.message + ' | prefix=' + cleaned.slice(0, 240));
}

const decision = String(parsed.decision ?? '').toUpperCase();
if (!['KEEP', 'SKIP'].includes(decision)) {
  throw new Error('Researcher decision must be KEEP or SKIP');
}

const facts = Array.isArray(parsed.facts)
  ? parsed.facts.map((fact) => ({
      claim: String(fact?.claim ?? ''),
      evidence: String(fact?.evidence ?? ''),
      confidence: String(fact?.confidence ?? 'LOW').toUpperCase(),
    }))
  : [];

const researchNotes = {
  decision,
  reason: String(parsed.reason ?? ''),
  event_type: String(parsed.event_type ?? 'OTHER').toUpperCase(),
  entities: Array.isArray(parsed.entities) ? parsed.entities.map(String) : [],
  market: Array.isArray(parsed.market) ? parsed.market.map(String) : [],
  event_time: parsed.event_time ?? null,
  source: String(parsed.source ?? base.source ?? ''),
  source_tier: String(parsed.source_tier ?? base.source_tier ?? ''),
  facts,
  market_relevance: String(parsed.market_relevance ?? ''),
  uncertainties: Array.isArray(parsed.uncertainties) ? parsed.uncertainties.map(String) : [],
};

if (!researchNotes.reason || !researchNotes.event_type || !facts.length) {
  throw new Error('Researcher output is missing required structured fields');
}

return [{
  json: {
    article_id: base.article_id,
    title: base.title,
    url: base.url,
    published_at: base.published_at,
    source: researchNotes.source,
    source_tier: researchNotes.source_tier,
    decision,
    research_notes: researchNotes,
    researcher_model: 'GLM-5.2',
  },
}];

