  .replace(/^\s*\`\`\`json\s*/i, '')
  .replace(/\s*\`\`\`\s*$/i, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  throw new Error('Reviewer JSON parse failed: ' + error.message + ' | prefix=' + cleaned.slice(0, 240));
}

const status = String(parsed.status ?? '').toUpperCase();
if (!['PASS', 'REJECT'].includes(status)) {
  throw new Error('Reviewer status must be PASS or REJECT');
}

const scores = parsed.scores && typeof parsed.scores === 'object' ? parsed.scores : {};
const issues = Array.isArray(parsed.issues) ? parsed.issues.map(String) : [];
const revisionBrief = Array.isArray(parsed.revision_brief)
  ? parsed.revision_brief.map(String)
  : [];

return [{
  json: {
    article_id: base.article_id,
    title: base.title,
    url: base.url,
    published_at: base.published_at,
    source: base.source,
    source_tier: base.source_tier,
    decision: base.decision,
    research_notes: base.research_notes,
    draft: base.draft,
    review: {
      status,
      scores,
      issues,
      revision_brief: revisionBrief,
    },
    reviewer_model: 'GLM-5.2',
  },
}];

const item = $input.first().json;

if (String(item.review?.status ?? '') !== 'PASS') {
  throw new Error('Publisher boundary only accepts Reviewer PASS');
}

return [{
  json: {
    publisher_status: 'PUBLISHER_BOUNDARY',
    published: false,
    destination: 'telegram_pending_credentials',
    article_id: item.article_id,
    title: item.title,
    url: item.url,
    published_at: item.published_at,
    source: item.source,
    headline: item.draft?.headline ?? '',
    telegram_copy: item.draft?.telegram_copy ?? '',
    review_status: item.review?.status ?? '',
    note: 'Telegram credential is not configured; final copy is retained for visible execution output.',
  },
}];

